{"code": "export async function main(input: { since: string }) {
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  let total = 0;
  let sawNext: string | null = null;
  const seenCursors = new Set<string>();
  do {
    const res = await sdk.github.listCommits({ since: input.since, cursor });
    pages++;
    for (const c of res.commits) {
      total++;
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
    }
    sawNext = res.nextCursor;
    if (sawNext !== null && seenCursors.has(sawNext)) break;
    if (sawNext !== null) seenCursors.add(sawNext);
    cursor = sawNext ?? undefined;
  } while (cursor !== undefined);
  return { pages, total, counts, lastNextCursor: sawNext };
