{"code": "export async function main(input: { since: string }) {
  const sinceMs = Date.parse(input.since);
  const all: { sha: string; email: string; at: string }[] = [];
  let cursor: string | undefined = undefined;
  const pageSizes: number[] = [];
  const cursors: (string | null)[] = [];
  let guard = 0;
  for (;;) {
    if (guard++ > 500) throw new Error("too many pages");
    const res = await sdk.github.listCommits({ since: input.since, cursor });
    pageSizes.push(res.commits.length);
    cursors.push(res.nextCursor);
    for (const c of res.commits) all.push({ sha: c.sha, email: c.authorEmail, at: c.committedAt });
    if (res.nextCursor === null) break;
    cursor = res.nextCursor;
  }
  const uniqueShas = new Set(all.map(c => c.sha));
  const before = all.filter(c => Date.parse(c.at) < sinceMs);
  const counts: Record<string, number> = {};
  for (const c of all) if (Date.parse(c.at) >= sinceMs) counts[c.email] = (counts[c.email] ?? 0) + 1;
  const sorted = [...all].sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  return {
    pageSizes, cursors, pages: pageSizes.length,
    fetched: all.length, uniqueShas: uniqueShas.size,
    beforeSince: before.length,
    oldest: sorted[0]?.at, newest: sorted[sorted.length - 1]?.at,
    counts,
  };
